// Deterministic pseudo-random generator to avoid Math.random() and prevent frame-flickering
const createSeedRandom = (seed: string) => {
  let h = 0;
  for (let i = 0; i < seed.length; i++) {
    h = Math.imul(31, h) + seed.charCodeAt(i) | 0;
  }
  return () => {
    let t = h += 0x6D2B79F5;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
};

// Generates an organic torn paper SVG path string
const getTornPath = (w: number, h: number, seed: string, step = 15, amplitude = 2.5) => {
  const rand = createSeedRandom(seed);
  let d = `M 0 0`;
  
  // Top edge
  for (let x = step; x < w; x += step) {
    const yOffset = (rand() - 0.5) * amplitude;
    d += ` L ${x} ${yOffset}`;
  }
  d += ` L ${w} 0`;
  
  // Right edge
  for (let y = step; y < h; y += step) {
    const xOffset = w + (rand() - 0.5) * amplitude;
    d += ` L ${xOffset} ${y}`;
  }
  d += ` L ${w} ${h}`;
  
  // Bottom edge
  for (let x = w - step; x > 0; x -= step) {
    const yOffset = h + (rand() - 0.5) * amplitude;
    d += ` L ${x} ${yOffset}`;
  }
  d += ` L 0 ${h}`;
  
  // Left edge
  for (let y = h - step; y > 0; y -= step) {
    const xOffset = (rand() - 0.5) * amplitude;
    d += ` L ${xOffset} ${y}`;
  }
  d += ` Z`;
  return d;
};

// Procedural organic highlighter stroke
const getHighlighterPath = (w: number, h: number, seed: string) => {
  const rand = createSeedRandom(seed);
  let d = `M 0 ${h * 0.1}`;
  
  // Top edge with slight waves
  for (let x = 10; x < w; x += 10) {
    const y = (rand() - 0.5) * 3;
    d += ` L ${x} ${y}`;
  }
  d += ` L ${w} ${h * 0.15}`;
  
  // Organic bleed on right edge
  d += ` Q ${w + 3} ${h * 0.5} ${w} ${h * 0.9}`;
  
  // Bottom edge
  for (let x = w - 10; x > 0; x -= 10) {
    const y = h + (rand() - 0.5) * 3;
    d += ` L ${x} ${y}`;
  }
  d += ` L 0 ${h * 0.85}`;
  
  // Left edge bleed
  d += ` Q -3 ${h * 0.5} 0 ${h * 0.1}`;
  d += ` Z`;
  return d;
};

