// Background Texture Paper Component (overlaying the entire animation)
const BackgroundTexture: React.FC<{
  width: number;
  height: number;
  strokeColor: string;
  grainDensity: number;
  grainOpacity: number;
}> = ({ width, height, strokeColor, grainDensity, grainOpacity }) => {
  const flecks = React.useMemo(() => {
    const rand = createSeedRandom("archival-paper-flecks");
    const count = grainDensity;
    const items = [];
    for (let i = 0; i < count; i++) {
      const x = rand() * width;
      const y = rand() * height;
      const length = rand() * 12 + 4;
      const angle = rand() * Math.PI * 2;
      const type = rand() > 0.45 ? "line" : "dot";
      const opacity = (rand() * 0.07 + 0.015) * grainOpacity;
      items.push({ x, y, length, angle, type, opacity });
    }
    return items;
  }, [width, height, grainDensity, grainOpacity]);

  return (
    <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 100 }}>
      {/* Subtle halftone/grid pattern overlay */}
      <svg width="100%" height="100%" style={{ position: "absolute", opacity: 0.03 * grainOpacity }}>
        <defs>
          <pattern id="gridPattern" width="24" height="24" patternUnits="userSpaceOnUse">
            <path d="M 24 0 L 0 0 0 24" fill="none" stroke={strokeColor} strokeWidth="1" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#gridPattern)" />
      </svg>
      {/* Organic flecks representing raw handmade fibers */}
      <svg width={width} height={height} style={{ position: "absolute" }}>
        {flecks.map((f, i) => {
          if (f.type === "line") {
            const x2 = f.x + Math.cos(f.angle) * f.length;
            const y2 = f.y + Math.sin(f.angle) * f.length;
            return (
              <line
                key={i}
                x1={f.x}
                y1={f.y}
                x2={x2}
                y2={y2}
                stroke={strokeColor}
                strokeWidth={1 + f.length * 0.04}
                opacity={f.opacity}
                strokeLinecap="round"
                style={{ transition: "none" }}
              />
            );
          } else {
            return (
              <circle
                key={i}
                cx={f.x}
                cy={f.y}
                r={1.2}
                fill={strokeColor}
                opacity={f.opacity * 1.6}
                style={{ transition: "none" }}
              />
            );
          }
        })}
      </svg>
    </div>
  );
};



export type ComponentNameProps = Record<string, any>;

