  // Layout proportions
  const containerWidth = width * 0.85;
  const containerHeight = height * 0.35;
  const containerX = (width - containerWidth) / 2;
  const containerY = height * 0.52; // Classic Lower-Third baseline placement

  const cardWidth = containerWidth * 0.64;
